CREATE TABLE password_vault (id UUID PRIMARY KEY DEFAULT uuid_v7(),owner_id UUID NOT NULL,name VARCHAR(256) NOT NULL,security_profile VARCHAR(64) NOT NULL,crypto_context TEXT NOT NULL,encrypted_recovery_key TEXT,status VARCHAR(24) NOT NULL DEFAULT 'LOCKED',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),version BIGINT NOT NULL DEFAULT 0,CHECK(security_profile='USER_LOCKED_E2EE'),CHECK(status IN ('LOCKED','UNLOCKED','ARCHIVED')),UNIQUE(owner_id,name)); CREATE TABLE password_vault_item (id UUID PRIMARY KEY DEFAULT uuid_v7(),vault_id UUID NOT NULL,owner_id UUID NOT NULL,item_type VARCHAR(32) NOT NULL,encrypted_name TEXT NOT NULL,encrypted_payload TEXT NOT NULL,encrypted_custom_fields TEXT,favorite BOOLEAN NOT NULL DEFAULT FALSE,revision BIGINT NOT NULL DEFAULT 1,tombstone BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),version BIGINT NOT NULL DEFAULT 0,FOREIGN KEY(vault_id) REFERENCES password_vault(id)); CREATE INDEX idx_password_item_vault ON password_vault_item(vault_id,owner_id,updated_at DESC);
